export function getProduct(slug: string): Product | undefined { return PRODUCTS.find((p) => p.slug === slug); }
export function productsByCollection(collection: Collection): Product[] { return PRODUCTS.filter((p) => p.collection === collection); }
export function productsByAudience(audience: Audience): Product[] { return PRODUCTS.filter((p) => p.audience === audience || p.audience === "all"); }
export function formatPrice(priceCents: number | null): string { if (priceCents === null) return "Price coming soon"; return `$${(priceCents / 100).toFixed(2)}`; }

